/* ---------- Hijri conversion & wasal-anniversary helpers ---------- */
/* Har mulk ki Ruet-e-Hilal (chaand dikhne ki) announcement alag hoti hai, is liye
   ek hi Gregorian din ko different mulk kabhi kabhi alag Hijri tareekh maante hain.
   Base calculation Umm al-Qura (Saudi) calendar par hai; owner apna mulk select
   karke ya manually ±din adjust karke isay apni mulk ki announcement se match kar
   sakta hai. Yehi adjustment Wasal ki Hijri tareekh aur Barsi alert dono par lagta hai. */
const HIJRI_COUNTRIES = [
  {code:'PK', label:'Pakistan',        adjust:-1},
  {code:'SA', label:'Saudi Arabia (Umm al-Qura)', adjust:0},
  {code:'IN', label:'India',           adjust:-1},
  {code:'BD', label:'Bangladesh',      adjust:-1},
  {code:'AE', label:'UAE / Gulf',      adjust:0},
  {code:'TR', label:'Turkey',          adjust:0},
  {code:'ID', label:'Indonesia',       adjust:-1},
  {code:'MY', label:'Malaysia',        adjust:-1},
  {code:'OTHER', label:'Other / Manual', adjust:0},
];
function hijriAdjustDays(){ return (DB.config && DB.config.hijriAdjustDays) || 0; }
function shiftDays(dateObj, days){ return new Date(dateObj.getTime() + days*86400000); }
/* Gregorian date -> Hijri, computed with plain arithmetic (civil/tabular Islamic calendar).
   We used to ask the browser to do this via Intl.DateTimeFormat(..., 'u-ca-islamic-umalqura'),
   but that silently depends on the device's ICU data: desktop Chrome/Edge ship the full
   Islamic-calendar tables, while many Android WebViews (the ones used inside file-manager /
   note-taking apps, not full Chrome) don't — and instead of throwing an error, they quietly
   fall back to the Gregorian calendar, so the "Hijri" date shown was actually just the
   Gregorian date again. Computing it ourselves removes that dependency entirely, so the
   result is identical on every device. (Being a tabular calendar, it can land a day or two
   off the official Umm al-Qura sighting-based date — that's what the Adjustment setting
   below is for.) */
const HIJRI_MONTHS = ['Muharram','Safar',"Rabi' al-Awwal","Rabi' al-Thani",'Jumada al-Awwal','Jumada al-Thani','Rajab',"Sha'ban",'Ramadan','Shawwal',"Dhu al-Qi'dah",'Dhu al-Hijjah'];
function gregorianToJDN(y,m,d){
  const a = Math.floor((14-m)/12);
  const y2 = y + 4800 - a;
  const m2 = m + 12*a - 3;
  return d + Math.floor((153*m2+2)/5) + 365*y2 + Math.floor(y2/4) - Math.floor(y2/100) + Math.floor(y2/400) - 32045;
}
function jdnToHijriParts(jdn){
  const epoch = 1948440;
  let l = jdn - epoch + 10632;
  const n = Math.floor((l-1)/10631);
  l = l - 10631*n + 354;
  const j = Math.floor((10985-l)/5316)*Math.floor((50*l)/17719) + Math.floor(l/5670)*Math.floor((43*l)/15238);
  l = l - Math.floor((30-j)/15)*Math.floor((17719*j)/50) - Math.floor(j/16)*Math.floor((15238*j)/43) + 29;
  const month = Math.floor((24*l)/709);
  const day = l - Math.floor((709*month)/24);
  const year = 30*n + j - 30;
  return {day, month, year};
}
function toHijri(isoDate){
  if(!isoDate) return '';
  const d = shiftDays(new Date(isoDate+'T12:00:00'), hijriAdjustDays());
  const {day, month, year} = jdnToHijriParts(gregorianToJDN(d.getFullYear(), d.getMonth()+1, d.getDate()));
  if(!day || !month || !year) return '';
  return `${day} ${HIJRI_MONTHS[month-1]}, ${year} AH`;
}
function hijriParts(dateObj){
  const shifted = shiftDays(dateObj, hijriAdjustDays());
  const o = jdnToHijriParts(gregorianToJDN(shifted.getFullYear(), shifted.getMonth()+1, shifted.getDate()));
  return (o.day && o.month && o.year) ? o : null;
}
/* Inverse of jdnToHijriParts — same "civil/tabular" Islamic calendar, same
   epoch, so the pair round-trips exactly (verified against 600+ dates
   spanning 1950-2070 before shipping). Needed for the Living Members
   Baligh-date calculation below: "this person's Hijri birthday, N Hijri
   years later" cannot be done with Gregorian year-arithmetic, since a
   Hijri year is ~354/355 days — it has to go through the Hijri calendar. */
function hijriToJDN(year, month, day){
  const epoch = 1948440;
  return day + Math.ceil(29.5*(month-1)) + (year-1)*354 + Math.floor((3+11*year)/30) + epoch - 1;
}
function jdnToGregorian(jdn){
  const a = jdn + 32044;
  const b = Math.floor((4*a+3)/146097);
  const c = a - Math.floor((146097*b)/4);
  const d2 = Math.floor((4*c+3)/1461);
  const e = c - Math.floor((1461*d2)/4);
  const m2 = Math.floor((5*e+2)/153);
  const day = e - Math.floor((153*m2+2)/5) + 1;
  const month = m2 + 3 - 12*Math.floor(m2/10);
  const year = 100*b + d2 - 4800 + Math.floor(m2/10);
  return {year, month, day};
}
function ymdISO(y,m,d){ return `${String(y).padStart(4,'0')}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`; }
// Adds N *Hijri* (qamari) years to a Gregorian ISO date and returns the
// resulting Gregorian ISO date — this is how "Baligh at 15 Hijri years old"
// actually has to be computed (a Hijri year is ~10-11 days shorter than a
// Gregorian one, so simply adding 15 to the Gregorian year would land on
// the wrong date by several months after a lifetime).
function addHijriYears(isoDob, years){
  const [gy,gm,gd] = isoDob.split('-').map(Number);
  const jdn = gregorianToJDN(gy,gm,gd);
  const h = jdnToHijriParts(jdn);
  const newYear = h.year + years;
  let day = h.day;
  // Guard the rare case a Hijri month-30 birth date lands on a 29-day
  // month N years later — clamp to that month's last real day instead of
  // silently overflowing into the next month.
  let testJdn = hijriToJDN(newYear, h.month, day);
  let back = jdnToHijriParts(testJdn);
  if(back.day!==day || back.month!==h.month || back.year!==newYear) day = day - 1;
  const finalJdn = hijriToJDN(newYear, h.month, day);
  const g = jdnToGregorian(finalJdn);
  return ymdISO(g.year, g.month, g.day);
}
// Pure ISO-string date arithmetic, anchored in UTC so it can never drift by
// a day depending on the device's timezone or daylight-saving changes.
function isoOffset(iso, deltaDays){
  const [y,m,d] = iso.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m-1, d) + deltaDays*86400000);
  return ymdISO(dt.getUTCFullYear(), dt.getUTCMonth()+1, dt.getUTCDate());
}
/* Owner ke config.anniversaryFormat ke mutabiq — 'hijri' select hai tu Agli Barsi
   Hijri calendar ki usi tareekh (month/day) par aayegi jis din Marhoom ka wasal hua tha,
   chahe Gregorian mein wo date har saal ~10-11 din peechay hi kyun na aaye.
   'gregorian' select hai tu Gregorian month/day par hi (jaisa pehlay tha). */
function nextAnniversary(isoDod){
  if(!isoDod) return null;
  const d = new Date(isoDod+'T12:00:00');
  const now = new Date();
  const todayOnly = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  if(DB.config.anniversaryFormat === 'hijri'){
    const dodH = hijriParts(d);
    if(dodH){
      for(let i=0;i<370;i++){
        const cand = new Date(todayOnly.getFullYear(), todayOnly.getMonth(), todayOnly.getDate()+i);
        const candH = hijriParts(cand);
        if(candH && candH.month===dodH.month && candH.day===dodH.day) return cand;
      }
    }
  }
  let next = new Date(now.getFullYear(), d.getMonth(), d.getDate());
  if(next < todayOnly) next = new Date(now.getFullYear()+1, d.getMonth(), d.getDate());
  return next;
}
function isAnniversaryToday(isoDod){
  if(!isoDod) return false;
  const d = new Date(isoDod+'T12:00:00');
  const now = new Date();
  if(DB.config.anniversaryFormat === 'hijri'){
    const dodH = hijriParts(d);
    const nowH = hijriParts(now);
    if(dodH && nowH) return dodH.month===nowH.month && dodH.day===nowH.day;
  }
  return d.getMonth()===now.getMonth() && d.getDate()===now.getDate();
}
function formatAnniversaryDate(dateObj){
  if(!dateObj) return '';
  if(DB.config.anniversaryFormat === 'hijri'){
    try{
      const d = shiftDays(dateObj, hijriAdjustDays());
      return new Intl.DateTimeFormat('en-TN-u-ca-islamic-umalqura', {day:'numeric', month:'long', year:'numeric'}).format(d);
    }
    catch(e){ return dateObj.toLocaleDateString(); }
  }
  return dateObj.toLocaleDateString();
}

function wasalBlock(m, s){
  if(!m.dod) return '';
  const hijri = m.dodHijri || toHijri(m.dod);
  const next = nextAnniversary(m.dod);
  const nextStr = next ? formatAnniversaryDate(next) : '';
  const annivToday = isAnniversaryToday(m.dod);
  let banner = '';
  if(annivToday){
    banner = `<div class="anniversary-banner rounded-lg p-3 mt-2 text-sm font-bold" style="background:var(--emerald-pale);color:var(--emerald-deep);border:1px solid var(--gold)">
      🕊️ Aaj <b>${esc(m.name)}</b> ki wasal barsi hai.
      ${s.totalPct>=100 ? ' Alhamdulillah — unki tamam Qaza Namaz mukammal ho chuki hai. Allah unhein maghfirat aur buland darjaat ata farmaye. Ameen 🤲' : ` Abhi ${s.totalRemaining} Qaza Namaz baqi hain — aaj khususi tor par unke liye Qaza ada karein.`}
    </div>`;
  } else if(s.totalPct>=100){
    banner = `<div class="rounded-lg p-3 mt-2 text-sm font-bold" style="background:var(--emerald-pale);color:var(--emerald-deep)">✅ Alhamdulillah — ${esc(m.name)} ki tamam Qaza Namaz mukammal ho chuki hai. Allah qabool farmaye. 🤲</div>`;
  }
  return `<div class="text-xs text-gray-500 mt-1">🕊️ Wasal: ${esc(m.dod)} <span class="text-gray-400">(${esc(hijri)})</span> · Agli Barsi: ${esc(nextStr)}</div>${banner}`;
}
function getActor(){
  if(!SESSION) return null;
  if(SESSION.role==='owner'){
    const acc = DB.config.ownerAccount||{};
    return {id:'owner', name:acc.name||'Family Owner', photo:acc.photo||null};
  }
  const mem = DB.members.find(m=>m.id===SESSION.memberId) || {};
  return {id:mem.id, name:mem.name, photo:mem.photo||null};
}

/* ---------------------------- DEFAULT DB ---------------------------- */
function defaultDB(){
  return {
    config:{
      familyName:'Our Family',
      logo:null,
      ownerAccount:null,   // {name,password,photo} set on first run
      anniversaryFormat:'gregorian',  // 'gregorian' or 'hijri' — which calendar the Barsi alert fires on
      hijriCountry:'PK',      // which country's moon-sighting convention to approximate (default Pakistan)
      hijriAdjustDays:-1,     // day-offset applied to the Umm al-Qura calendar for that country
      driveAccountEmail:null,  // once set, only this Gmail may connect Google Drive for this family
      baligh:{ maleHijriYears:15, femaleHijriYears:9 } // age (in Hijri/qamari years) at which Namaz becomes Wajib — adjustable in Settings
    },
    marhooms:[],   // {id,name,relation,gender,dob(Gregorian),dod(Gregorian),dodHijri,photo,targets:{fajr,zuhr,asr,maghrib,isha},updatedAt}
    members:[],    // {id,name,relation,password,photo,updatedAt}
    progress:{},   // marhoomId -> actorId('owner' or memberId) -> {fajr,zuhr,asr,maghrib,isha}
    activity:[],   // [{id,ts,marhoomId,memberId,prayer,delta}] most recent first, capped at 300
    // Tombstones remember WHAT was deleted and WHEN, so that merging this
    // device's data with another device's (possibly older/stale) copy of
    // the family record can never accidentally "resurrect" something that
    // was deliberately removed — see mergeDB() below.
    tombstones:{ marhooms:[], members:[] },
    // meta.savedAt is stamped on every local change (see saveDB) and is
    // what mergeDB() and the Drive sync logic use to reconcile two copies
    // of the record without ever silently throwing away newer data.
    meta:{ savedAt:0 }
  };
}
let DB = loadDB();
function loadDB(){
  try{
    const raw = localStorage.getItem(DB_KEY);
    if(!raw) return defaultDB();
    const parsed = JSON.parse(raw);
    const d = defaultDB();
    return Object.assign(d, parsed, {
      config: Object.assign(d.config, parsed.config||{}),
      tombstones: Object.assign(d.tombstones, parsed.tombstones||{}),
      meta: Object.assign(d.meta, parsed.meta||{})
    });
  }catch(e){ return defaultDB(); }
}
function saveDB(){
  DB.meta.savedAt = Date.now();
  try{
    localStorage.setItem(DB_KEY, JSON.stringify(DB));
  }catch(e){
    // Most common cause: a full-resolution camera photo pushed this
    // device's storage over its quota. We still keep going (the data
    // stays correct in memory for this session) but we tell the user
    // plainly, because silently failing here is exactly what used to
    // make a newly-added Marhoom "disappear" after a reload.
    console.error('localStorage save failed', e);
    alert('⚠️ Is device ki local storage bhar chuki hai, is liye yeh tabdeeli save nahi ho saki. Tasveer ka size chhota karein ya Settings > Local File Backup se purana backup safely download kar ke local storage khali karein, phir dobara try karein.');
  }
  scheduleAutoSync();
}

/* ============================================================
   MERGE — combines two copies of the family record (this device's
   and Google Drive's) into one, WITHOUT ever losing data:
     - marhooms/members: kept from both sides; if the same person was
       edited on both sides, the more-recently-edited version wins.
     - a deletion always wins over a stale copy that doesn't know about
       it yet (tombstones), but never over an edit made AFTER the delete.
     - prayer counts: the higher count wins per prayer, so a sync can
       never make someone's completed prayers go backwards.
     - activity log: combined and de-duplicated by id.
   This is what lets every family member's device push its own updates
   and pull everyone else's without anyone ever needing to "resolve a
   conflict" by hand, and without a stale device ever overwriting newer
   work from someone else.
   ============================================================ */
function mergeTombstones(listA, listB){
  const map = new Map();
  [...(listA||[]), ...(listB||[])].forEach(t=>{
    if(!t || !t.id) return;
    const existing = map.get(t.id);
    if(!existing || (t.deletedAt||0) > (existing.deletedAt||0)) map.set(t.id, t);
  });
  return Array.from(map.values()).sort((x,y)=>(y.deletedAt||0)-(x.deletedAt||0)).slice(0,500);
}
function mergeById(listA, listB, tombstones){
  const map = new Map();
  (listB||[]).forEach(item=>{ if(item && item.id) map.set(item.id, item); });
  (listA||[]).forEach(item=>{
    if(!item || !item.id) return;
    const existing = map.get(item.id);
    if(!existing){ map.set(item.id, item); return; }
    const ta = item.updatedAt||0, tb = existing.updatedAt||0;
    map.set(item.id, ta>=tb ? item : existing);
  });
  const tomb = new Map((tombstones||[]).map(t=>[t.id, t.deletedAt||0]));
  return Array.from(map.values()).filter(item=> !(tomb.has(item.id) && tomb.get(item.id) >= (item.updatedAt||0)));
}
function mergeDB(a, b){
  a = a || defaultDB(); b = b || defaultDB();
  const out = defaultDB();
  const aTs = (a.meta&&a.meta.savedAt)||0, bTs = (b.meta&&b.meta.savedAt)||0;
  const newer = aTs>=bTs ? a : b, older = newer===a ? b : a;

  out.config = Object.assign({}, defaultDB().config, newer.config||{});
  // Owner identity (name/password/photo) must win merge on ITS OWN
  // timestamp, not on which device's whole save happened to be newest.
  // Reason: a Family-Owner change (e.g. promoting a new Owner) is a
  // specific, timestamped event — but the OTHER device (the new Owner's
  // own device, say) can easily rack up a LATER overall save afterwards
  // just from ordinary activity (marking a daily prayer) before it ever
  // syncs. Under the old "whole config from the newer whole-DB side"
  // rule, that later-but-unrelated save would silently overwrite the
  // promotion and revert the Owner back to the old one. Comparing each
  // side's ownerAccount.updatedAt directly avoids that.
  {
    const aOA = (a.config && a.config.ownerAccount) || null;
    const bOA = (b.config && b.config.ownerAccount) || null;
    if(aOA && bOA) out.config.ownerAccount = (aOA.updatedAt||0) >= (bOA.updatedAt||0) ? aOA : bOA;
    else out.config.ownerAccount = aOA || bOA || null; // safety net: never un-set an already-created Owner
  }
  if(!out.config.driveAccountEmail) out.config.driveAccountEmail = (older.config&&older.config.driveAccountEmail) || null;

  out.tombstones = {
    marhooms: mergeTombstones((a.tombstones&&a.tombstones.marhooms)||[], (b.tombstones&&b.tombstones.marhooms)||[]),
    members: mergeTombstones((a.tombstones&&a.tombstones.members)||[], (b.tombstones&&b.tombstones.members)||[])
  };
  out.marhooms = mergeById(a.marhooms||[], b.marhooms||[], out.tombstones.marhooms);
  out.members  = mergeById(a.members||[], b.members||[], out.tombstones.members);

  /* Field-level safety net for Living Members data. mergeById above picks
     one whole member record when both sides edited the same person
     (whichever has the newer updatedAt) — fine for name/password/photo,
     but a member could mark their own daily prayers from two different
     devices (phone + tablet) before either syncs. Picking only one side's
     whole record would silently drop the OTHER device's marks. So we
     separately re-merge dailyMarks (a date/waqt is "done" if EITHER side
     says so — a tick is never lost) and qazaAda (the same safe
     running-max merge already used for Marhoom progress above) from BOTH
     copies, regardless of which whole record mergeById picked. */
  const aMemMap = new Map((a.members||[]).map(m=>[m.id,m]));
  const bMemMap = new Map((b.members||[]).map(m=>[m.id,m]));
  out.members = out.members.map(mem=>{
    const am = aMemMap.get(mem.id), bm = bMemMap.get(mem.id);
    if(!am && !bm) return mem;
    const dm = {};
    [am, bm].forEach(src=>{
      if(!src || !src.dailyMarks) return;
      Object.keys(src.dailyMarks).forEach(date=>{
        const day = src.dailyMarks[date] || {};
        PRAYERS.forEach(p=>{ if(day[p.key]){ if(!dm[date]) dm[date]={}; dm[date][p.key]=true; } });
      });
    });
    const qa = {};
    PRAYERS.forEach(p=>{ qa[p.key] = Math.max(Number(am?.qazaAda?.[p.key])||0, Number(bm?.qazaAda?.[p.key])||0); });
    // profile is written once at registration and never edited again — if
    // (extremely rarely) both sides show a registration, keep whichever
    // happened first so this resolves the same way on every device.
    let profile = am?.profile || bm?.profile || mem.profile || null;
    if(am?.profile?.registeredAt && bm?.profile?.registeredAt){
      profile = am.profile.registeredAt <= bm.profile.registeredAt ? am.profile : bm.profile;
    }
    return Object.assign({}, mem, { dailyMarks: dm, qazaAda: qa, profile });
  });

  // Same field-level safety net as above, but for the Owner's own
  // self-tracking (DB.config.ownerAccount) — an Owner can also mark their
  // own daily prayers/Qaza from more than one device.
  if(out.config.ownerAccount){
    const ao = a.config && a.config.ownerAccount, bo = b.config && b.config.ownerAccount;
    if(ao || bo){
      const dm = {};
      [ao, bo].forEach(src=>{
        if(!src || !src.dailyMarks) return;
        Object.keys(src.dailyMarks).forEach(date=>{
          const day = src.dailyMarks[date] || {};
          PRAYERS.forEach(p=>{ if(day[p.key]){ if(!dm[date]) dm[date]={}; dm[date][p.key]=true; } });
        });
      });
      const qa = {};
      PRAYERS.forEach(p=>{ qa[p.key] = Math.max(Number(ao?.qazaAda?.[p.key])||0, Number(bo?.qazaAda?.[p.key])||0); });
      let profile = ao?.profile || bo?.profile || out.config.ownerAccount.profile || null;
      if(ao?.profile?.registeredAt && bo?.profile?.registeredAt){
        profile = ao.profile.registeredAt <= bo.profile.registeredAt ? ao.profile : bo.profile;
      }
      out.config.ownerAccount = Object.assign({}, out.config.ownerAccount, { dailyMarks: dm, qazaAda: qa, profile });
    }
  }

  const liveMarhoomIds = new Set(out.marhooms.map(m=>m.id));
  out.progress = {};
  const marhoomIds = new Set([...Object.keys(a.progress||{}), ...Object.keys(b.progress||{})]);
  marhoomIds.forEach(mid=>{
    if(!liveMarhoomIds.has(mid)) return; // don't resurrect progress for a deleted Marhoom
    const pa=(a.progress||{})[mid]||{}, pb=(b.progress||{})[mid]||{};
    const actorIds = new Set([...Object.keys(pa), ...Object.keys(pb)]);
    out.progress[mid] = {};
    actorIds.forEach(aid=>{
      const ca=pa[aid]||{}, cb=pb[aid]||{}; const rec={};
      PRAYERS.forEach(p=>{ rec[p.key] = Math.max(Number(ca[p.key])||0, Number(cb[p.key])||0); });
      out.progress[mid][aid] = rec;
    });
  });

  const actMap = new Map();
  [...(b.activity||[]), ...(a.activity||[])].forEach(act=>{ if(act && act.id && liveMarhoomIds.has(act.marhoomId)) actMap.set(act.id, act); });
  out.activity = Array.from(actMap.values()).sort((x,y)=>y.ts-x.ts).slice(0,300);

  out.meta = { savedAt: Math.max(aTs, bTs) };
  return out;
}

/* ---------- Photo compression ----------
   Phone camera photos are often 3-8 MB each. Storing that as base64 in
   localStorage (which typically has only ~5-10 MB of room total, shared
   by the ENTIRE app) fills it up after just one or two photos, and every
   save after that silently fails — which is exactly what caused newly
   added Marhoom/Member records to vanish after a reload. This shrinks
   every photo to a small, sharp-enough JPEG before it's ever stored. */
function compressImage(file, maxDim, quality){
  maxDim = maxDim || 480; quality = quality==null ? 0.72 : quality;
  return new Promise((resolve, reject)=>{
    if(!file){ resolve(null); return; }
    const reader = new FileReader();
    reader.onerror = ()=>reject(new Error('Tasveer parhi nahi ja saki.'));
    reader.onload = (e)=>{
      const img = new Image();
      img.onerror = ()=>resolve(e.target.result); // fall back to the original rather than losing the photo
      img.onload = ()=>{
        try{
          let width = img.naturalWidth, height = img.naturalHeight;
          if(width > maxDim || height > maxDim){
            if(width >= height){ height = Math.round(height*(maxDim/width)); width = maxDim; }
            else { width = Math.round(width*(maxDim/height)); height = maxDim; }
          }
          const canvas = document.createElement('canvas');
          canvas.width = width; canvas.height = height;
          canvas.getContext('2d').drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', quality));
        }catch(err){ resolve(e.target.result); }
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  });
}

