function ownerExists(){ return !!(DB.config.ownerAccount && DB.config.ownerAccount.name && DB.config.ownerAccount.password); }
function selectRole(role){
  CURRENT_ROLE = role;
  document.querySelectorAll('.role-tab').forEach(b=>b.classList.toggle('active', b.dataset.role===role));
  const box = document.getElementById('loginFields');
  if(role==='owner'){
    if(!ownerExists()){
      box.innerHTML = `<p class="text-xs text-gray-500 mb-3">First time here — create the Family Owner login.</p>
        <label class="block text-sm font-bold mb-1">Your Name</label>
        <input id="ownNewName" type="text" class="w-full border rounded-lg px-3 py-2 mb-3" placeholder="e.g. Ahmed Khan">
        <label class="block text-sm font-bold mb-1">Create Password</label>
        <input id="ownNewPass" type="password" class="w-full border rounded-lg px-3 py-2 mb-3" placeholder="Choose a password">
        <label class="block text-sm font-bold mb-1">Confirm Password</label>
        <input id="ownNewPass2" type="password" class="w-full border rounded-lg px-3 py-2" placeholder="Re-enter password">`;
    } else {
      box.innerHTML = `<label class="block text-sm font-bold mb-1">Your Name</label>
        <input id="loginName" type="text" class="w-full border rounded-lg px-3 py-2 mb-3" placeholder="Enter your name">
        <label class="block text-sm font-bold mb-1">Password</label>
        <input id="loginPass" type="password" class="w-full border rounded-lg px-3 py-2" placeholder="Enter password">`;
    }
  } else {
    if(!DB.members.length){
      box.innerHTML = `<p class="text-sm text-amber-700 bg-amber-50 border border-amber-200 rounded-lg p-3">No family members added yet. Ask the Family Owner to add you first.</p>`;
    } else {
      const opts = DB.members.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('');
      box.innerHTML = `<label class="block text-sm font-bold mb-1">Your Name</label>
        <select id="loginMember" class="w-full border rounded-lg px-3 py-2 mb-3">${opts}</select>
        <label class="block text-sm font-bold mb-1">Password</label>
        <input id="loginPass" type="password" class="w-full border rounded-lg px-3 py-2" placeholder="Enter password">`;
    }
  }
}
function showErr(msg){ const e=document.getElementById('loginErr'); e.textContent=msg; e.classList.remove('hidden'); }
function doLogin(){
  document.getElementById('loginErr')?.classList.add('hidden');
  if(CURRENT_ROLE==='owner'){
    if(!ownerExists()){
      const name = document.getElementById('ownNewName').value.trim();
      const p1 = document.getElementById('ownNewPass').value;
      const p2 = document.getElementById('ownNewPass2').value;
      if(!name || !p1){ showErr('Please enter your name and a password.'); return; }
      if(p1.length<4){ showErr('Password should be at least 4 characters.'); return; }
      if(p1!==p2){ showErr('Passwords do not match.'); return; }
      DB.config.ownerAccount = {name, password:p1, photo:null, updatedAt: Date.now()};
      saveDB(); setSession({role:'owner'}); render(); return;
    }
    const name = document.getElementById('loginName').value.trim();
    const pass = document.getElementById('loginPass').value;
    const acc = DB.config.ownerAccount;
    if(name.toLowerCase()===String(acc.name).toLowerCase() && pass===acc.password){ setSession({role:'owner'}); render(); }
    else {
      // Common cause of a "wrong password" report that is NOT actually a
      // wrong password: this device's local copy of the family record is
      // stale (e.g. someone was just promoted to Owner on a DIFFERENT
      // device, and that change hasn't reached this device yet). A dead
      // giveaway is that the name typed still matches an existing Family
      // Member on THIS device's local data, even though it no longer
      // matches the Owner account here.
      const staleMemberMatch = DB.members.find(m=>m.name.toLowerCase()===name.toLowerCase());
      if(staleMemberMatch){
        showErr('Ye naam is device par abhi bhi "Family Member" list mein hai — matlab is device ne family ka naya (updated) record abhi tak sync nahi kiya. Neeche "☁️ Load My Family\'s Data (Google Drive)" button dabayein aur family ki wahi shared Gmail se sign-in karein, phir dobara isi password se Owner Log In try karein.');
      } else {
        showErr('Incorrect name or password.');
      }
    }
  } else {
    if(!DB.members.length){ showErr('No family members added yet.'); return; }
    const mid = document.getElementById('loginMember').value;
    const pass = document.getElementById('loginPass').value;
    const member = DB.members.find(m=>m.id===mid);
    if(member && pass===member.password){ setSession({role:'member', memberId:mid}); render(); }
    else showErr('Incorrect password.');
  }
}

