let DRIVE_TOKEN = null;
let DRIVE_TOKEN_CLIENT = null;
let DRIVE_LAST_SYNC = null;
let AUTO_SYNC_TIMER = null;

/* ============================================================
   PERSISTED ACCESS TOKEN
   A Google access token is normally kept only in memory, so it was
   wiped on every page reload — meaning EVERY reload needed a fresh
   token before Drive would work again. That refresh was requested
   "silently" (no popup), but silent refresh only succeeds if this
   exact browser still has an active Google session for the exact
   family Gmail — which often isn't the case on a family member's own
   phone (their phone/Chrome is normally signed into THEIR personal
   Gmail, not the shared family one), so the silent attempt failed
   and they were stuck seeing "Connect" again on every visit, even
   though nothing was actually wrong with their earlier connection.
   Fix: remember the token itself (and when it expires — Google's
   tokens last about an hour) in localStorage. A reload can then keep
   using that same still-valid token immediately, with zero contact
   with Google at all, exactly like the Owner's device does. Signing
   out of Google in the browser later does NOT revoke an
   already-issued token, so this keeps working across that too — the
   token only needs to be renewed once it actually expires.
   ============================================================ */
const DRIVE_TOKEN_KEY = 'qaza_drive_token';
const DRIVE_TOKEN_EXP_KEY = 'qaza_drive_token_exp';
function persistDriveToken(token, expiresInSeconds){
  try{
    localStorage.setItem(DRIVE_TOKEN_KEY, token);
    localStorage.setItem(DRIVE_TOKEN_EXP_KEY, String(Date.now() + (Number(expiresInSeconds)||3300)*1000));
  }catch(e){}
}
function clearPersistedDriveToken(){
  try{ localStorage.removeItem(DRIVE_TOKEN_KEY); localStorage.removeItem(DRIVE_TOKEN_EXP_KEY); }catch(e){}
}
// `minRemainingMs` lets a caller ask for a token with some safety margin
// left on it (e.g. "at least 5 more minutes"), not just "not expired yet".
function loadPersistedDriveToken(minRemainingMs){
  try{
    const token = localStorage.getItem(DRIVE_TOKEN_KEY);
    const exp = Number(localStorage.getItem(DRIVE_TOKEN_EXP_KEY)||0);
    if(token && exp && (exp - Date.now()) > (minRemainingMs||60000)) return {token, exp};
  }catch(e){}
  return null;
}
function scheduleAutoSync(){
  if(!DRIVE_TOKEN || !navigator.onLine) return;
  clearTimeout(AUTO_SYNC_TIMER);
  AUTO_SYNC_TIMER = setTimeout(()=>{
    AUTO_SYNC_TIMER = null; // IMPORTANT: must be cleared once it fires, or driveAutoPull()
                             // below would see it as "still pending" forever after the very
                             // first edit ever made on this device, and would stop pulling in
                             // everyone else's updates for the rest of time.
    const before = JSON.stringify(DB);
    driveReconcile().then(result=>{
      if(result.ok && JSON.stringify(DB)!==before && SESSION) render();
    });
  }, 2500);
}
window.addEventListener('online', ()=>{ if(DRIVE_TOKEN) driveSave(true); else { attemptSilentDriveReconnect(); if(SESSION) render(); } });
window.addEventListener('offline', ()=>{ if(SESSION) render(); });
async function fetchGoogleEmail(token){
  try{
    const res = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {headers:{Authorization:'Bearer '+token}});
    if(!res.ok) return null;
    const data = await res.json();
    return data.email || null;
  }catch(e){ return null; }
}
function driveConnect(){
  const cid = GOOGLE_CLIENT_ID;
  if(!cid){ alert('Google Drive sync abhi is website ke liye taiyar nahi — website chalane wale se rabta karein.'); return; }
  if(typeof google==='undefined' || !google.accounts){ alert('Google sign-in load nahi ho saka. Internet connection check karein aur yaqeeni banayein ke ye app kisi https:// address par host hai (local file:// par kaam nahi karti).'); return; }
  DRIVE_TOKEN_CLIENT = google.accounts.oauth2.initTokenClient({
    client_id: cid,
    scope: DRIVE_SCOPE,
    callback: async (resp)=>{
      if(resp.error){ alert('Google se connect nahi ho saka: '+resp.error); return; }
      const email = await fetchGoogleEmail(resp.access_token);
      const lockedEmail = DB.config.driveAccountEmail;
      if(lockedEmail && email && email.toLowerCase()!==lockedEmail.toLowerCase()){
        alert(`Ye family ki Google Drive sirf "${lockedEmail}" account par fix hai. Aap ne "${email}" se sign-in kiya, jo match nahi karta — is liye connect nahi kiya gaya. Sahi family Gmail account se dobara try karein (ya Owner "Drive account badlein" wala option use kare).`);
        return;
      }
      DRIVE_TOKEN = resp.access_token;
      localStorage.setItem('qaza_drive_connected','1');
      persistDriveToken(resp.access_token, resp.expires_in);
      if(!DB.config.driveAccountEmail && email) DB.config.driveAccountEmail = email;
      saveDB();
      // Safely merge whatever is already on this family's Drive with
      // whatever this device already has locally — nothing on either
      // side is lost, no matter which one is "older".
      const result = await driveReconcile();
      if(result.ok){
        alert(result.hadRemote
          ? '✅ Google Drive se connect ho gaya! Family ka poora maujooda record (Marhoom, Members, Progress) is device ke record ke saath surakshit tareeqe se mila diya gaya hai — kisi ka bhi data zaya nahi hua.'
          : 'Google Drive se connect ho gaya! Ye is family ki pehli backup hai — is device ka maujooda record ab yahan se save hota rahega, aur har doosra device isi Gmail se connect karke yahi record turant paa lega.');
      } else {
        alert('Connect ho gaya, lekin record sync karte waqt masla aaya: '+(result.reason||'')+'\nThodi dair mein khud-ba-khud dobara koshish hogi.');
      }
      render();
    }
  });
  DRIVE_TOKEN_CLIENT.requestAccessToken({hint: DB.config.driveAccountEmail || ''});
}
function driveChangeAccount(){
  if(!confirm('Kya aap waqai family ki Google Drive account badalna chahte hain?\n\nIs ke baad har device par dobara "Connect" karke sahi (naye) Gmail account se sign-in karna hoga.')) return;
  DB.config.driveAccountEmail = null;
  DRIVE_TOKEN = null;
  localStorage.removeItem('qaza_drive_connected');
  clearPersistedDriveToken();
  saveDB();
  render();
}
// A saved/refreshed token can still turn out to be dead (expired early,
// revoked, clock skew, etc). Rather than sit "connected" forever with a
// token that no longer works, drop it here and let the heartbeat in
// initDriveConnection() quietly get a fresh one on its next tick.
function handleDriveAuthFailure(){
  DRIVE_TOKEN = null;
  clearPersistedDriveToken();
}
async function driveFindFileId(){
  const q = encodeURIComponent(`name='qaza-tracker-backup.json' and trashed=false`);
  const res = await fetch(`https://www.googleapis.com/drive/v3/files?q=${q}&spaces=drive&fields=files(id,name)`, {
    headers:{Authorization:'Bearer '+DRIVE_TOKEN}
  });
  if(!res.ok){
    if(res.status===401) handleDriveAuthFailure();
    let detail = res.status;
    try{ const errJson = await res.json(); if(errJson.error && errJson.error.message) detail = `${res.status} — ${errJson.error.message}`; }catch(e){}
    throw new Error(`Drive se file list nahi mili (${detail}).`);
  }
  const data = await res.json();
  return (data.files && data.files[0]) ? data.files[0].id : null;
}
async function driveUpload(fileId, jsonString){
  const boundary='qazaboundary';
  const metaPart = fileId ? '{}' : JSON.stringify({name:'qaza-tracker-backup.json', mimeType:'application/json'});
  const body =
    `--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${metaPart}\r\n`+
    `--${boundary}\r\nContent-Type: application/json\r\n\r\n${jsonString}\r\n--${boundary}--`;
  const url = fileId
    ? `https://www.googleapis.com/upload/drive/v3/files/${fileId}?uploadType=multipart`
    : `https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart`;
  const res = await fetch(url, {
    method: fileId?'PATCH':'POST',
    headers:{Authorization:'Bearer '+DRIVE_TOKEN, 'Content-Type':`multipart/related; boundary=${boundary}`},
    body
  });
  if(!res.ok){
    if(res.status===401) handleDriveAuthFailure();
    throw new Error(await res.text());
  }
  if(fileId) return fileId;
  const created = await res.json();
  return created.id;
}
function loginConnectAndLoad(){
  const cid = GOOGLE_CLIENT_ID;
  const msg = document.getElementById('loginDriveMsg');
  const setMsg = (t,ok)=>{ if(!msg) return; msg.textContent=t; msg.style.color = ok?'var(--emerald)':'#b3403a'; msg.classList.remove('hidden'); };
  if(!cid){ setMsg('Google Drive sync abhi is website ke liye taiyar nahi — website chalane wale se rabta karein.', false); return; }
  if(typeof google==='undefined' || !google.accounts){ setMsg('Google sign-in load nahi ho saka — internet check karein aur yaqeeni banayein ye app https:// par host hai.', false); return; }
  const client = google.accounts.oauth2.initTokenClient({
    client_id: cid,
    scope: DRIVE_SCOPE,
    callback: async (resp)=>{
      if(resp.error){ setMsg('Google se connect nahi ho saka: '+resp.error, false); return; }
      const email = await fetchGoogleEmail(resp.access_token);
      const lockedEmail = DB.config.driveAccountEmail;
      if(lockedEmail && email && email.toLowerCase()!==lockedEmail.toLowerCase()){
        setMsg(`Ye device pehle se "${lockedEmail}" family account ke saath set hai. "${email}" se record load nahi kiya ja sakta — sahi family Gmail se try karein.`, false);
        return;
      }
      DRIVE_TOKEN = resp.access_token;
      localStorage.setItem('qaza_drive_connected','1');
      persistDriveToken(resp.access_token, resp.expires_in);
      setMsg('Record dhoonda ja raha hai…', true);
      const result = await driveReconcile();
      if(!result.ok){ setMsg('Family record load nahi ho saka: '+(result.reason||''), false); return; }
      if(!result.hadRemote){
        setMsg('Is Gmail par abhi koi family record nahi mila. Agar aap naye Family Owner hain to upar se "Continue" dabakar apni family shuru karein — connect hone ke baad data khud isi Drive par save hota rahega.', false);
        return;
      }
      if(!DB.config.driveAccountEmail && email){ DB.config.driveAccountEmail = email; saveDB(); }
      alert('✅ Family ka record mil gaya! Ab apna naam/role chun kar apne password se Log In karein.');
      render();
    }
  });
  client.requestAccessToken({hint: DB.config.driveAccountEmail || ''});
}

/* ============================================================
   RECONCILE — the single place that talks to Drive for both saving
   AND loading. Every entry point below (manual buttons, silent
   reconnect on page load, the 20-second auto-pull, the debounced
   auto-save after an edit) all funnel through here, so there is only
   ONE code path that can touch the shared file — which is what
   guarantees a stale device can never clobber someone else's newer
   update, and a fresh device always ends up with everyone's data.
   Sequence: fetch whatever is currently on Drive -> merge it with
   this device's copy (mergeDB, see above) -> save the merged result
   locally -> and, only if the merge actually changed anything versus
   what's on Drive, push the merged result back up.
   ============================================================ */
/* Every caller (manual buttons, silent reconnect, the periodic auto-pull,
   the debounced auto-save) used to be turned away with reason:'busy' if a
   reconcile was already in flight — which meant that exact update was
   simply dropped: it was never retried automatically, so a member's very
   first "Connect" could quietly fail to ever create/merge into the shared
   file, and they'd see "busy" with no real recovery besides luck on the
   next timer tick. Now every call is QUEUED behind whichever reconcile is
   currently running (still only one network round-trip happens at a
   time — nothing is more concurrent than before), so nobody's update is
   ever silently discarded; it just runs a moment later. */
let DRIVE_SYNC_QUEUE = Promise.resolve();
function driveReconcile(){
  const run = async () => {
    if(!DRIVE_TOKEN) return {ok:false, reason:'not-connected'};
    if(!navigator.onLine) return {ok:false, reason:'offline'};
    try{
      let fileId = await driveFindFileId();
      let remoteText = null, remoteData = null;
      if(fileId){
        const res = await fetch(`https://www.googleapis.com/drive/v3/files/${fileId}?alt=media`, {headers:{Authorization:'Bearer '+DRIVE_TOKEN}});
        if(res.ok){
          remoteText = await res.text();
          try{ remoteData = JSON.parse(remoteText); }catch(e){ remoteData = null; }
        } else if(res.status===401){
          handleDriveAuthFailure();
          return {ok:false, reason:'unauthorized'};
        }
      }
      const merged = remoteData ? mergeDB(DB, remoteData) : DB;
      const mergedJSON = JSON.stringify(merged);
      DB = merged;
      try{ localStorage.setItem(DB_KEY, mergedJSON); }catch(e){ /* surfaced already by saveDB elsewhere */ }
      let pushed = false;
      if(!fileId || mergedJSON !== remoteText){
        fileId = await driveUpload(fileId, mergedJSON);
        pushed = true;
      }
      DRIVE_LAST_SYNC = new Date();
      return {ok:true, fileId, pushed, hadRemote: !!remoteData};
    }catch(e){
      return {ok:false, reason:e.message};
    }
  };
  const result = DRIVE_SYNC_QUEUE.then(run, run);
  // Keep the chain alive even though `run` itself never rejects, so one
  // bad turn can never wedge every reconcile call after it.
  DRIVE_SYNC_QUEUE = result.catch(()=>{});
  return result;
}
async function driveSave(silent){
  if(!DRIVE_TOKEN){ if(!silent) alert('Pehle Google Drive se connect karein.'); return; }
  if(!navigator.onLine){ if(!silent) alert('Aap abhi offline hain — jese hi internet aayega, ye khud save ho jayega.'); return; }
  const result = await driveReconcile();
  if(result.ok){
    if(!silent) alert('✅ Family ka poora record Google Drive par save ho gaya — aur agar kisi doosre member ne kuch add kiya tha, wo bhi is device par aa gaya hai.');
    if(SESSION) render();
  } else if(!silent){
    alert('Drive par save nahi ho saka: '+(result.reason||'Nampata wajah')+'\nThodi dair mein khud-ba-khud dobara koshish hogi.');
  }
}
async function driveLoad(){
  if(!DRIVE_TOKEN){ alert('Pehle Google Drive se connect karein.'); return; }
  const result = await driveReconcile();
  if(result.ok){
    alert(result.hadRemote ? '✅ Drive ka latest record is device ke record ke saath mila diya gaya — koi bhi data zaya nahi hua.' : 'Abhi Drive par is family ka koi record nahi mila.');
    render();
  } else {
    alert('Drive se load nahi ho saka: '+(result.reason||''));
  }
}
function exportData(){
  const blob = new Blob([JSON.stringify(DB,null,2)], {type:'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = `qaza-backup-${todayISO()}.json`; a.click();
  URL.revokeObjectURL(url);
}
function importData(input){
  const file = input.files[0]; if(!file) return;
  const reader = new FileReader();
  reader.onload = async (e)=>{
    try{
      const data = JSON.parse(e.target.result);
      if(!confirm('This will replace all current data on this device with the backup file. Continue?')) return;
      const d = defaultDB();
      DB = Object.assign(d, data, {
        config: Object.assign(d.config, data.config||{}),
        tombstones: Object.assign(d.tombstones, data.tombstones||{}),
        meta: { savedAt: Date.now() } // treat a restored backup as a brand-new local change so it syncs to Drive
      });
      saveDB();
      if(DRIVE_TOKEN) await driveReconcile();
      alert('Backup restored successfully!'); render();
    }catch(err){ alert('Could not read this file — please choose a valid backup JSON.'); }
  };
  reader.readAsText(file);
}

