const MEMBER_TABS = [
  {key:'markdone', label:'Ada Karein', icon:'🤲'},
  {key:'myqaza', label:'Meri Namaz', icon:'🙏'},
  {key:'living', label:'Zinda Members', icon:'🧍'},
  {key:'progress', label:'Family Progress', icon:'📊'},
  {key:'dua', label:'Dua & Maghfirat', icon:'📿'},
  {key:'sync', label:'Google Drive', icon:'☁️'},
  {key:'activity', label:'Activity Log', icon:'📜'},
  {key:'directory', label:'Family Directory', icon:'👨‍👩‍👧‍👦'},
  {key:'about', label:'About', icon:'ℹ️'},
];
function renderMember(){
  const member = DB.members.find(m=>m.id===SESSION.memberId);
  if(!member){ logout(); return; }
  if(!ACTIVE_TAB || !MEMBER_TABS.find(t=>t.key===ACTIVE_TAB)) ACTIVE_TAB='markdone';
  let content='';
  if(ACTIVE_TAB==='markdone') content = mMarkDone(getActor());
  if(ACTIVE_TAB==='myqaza') content = mMyQaza();
  if(ACTIVE_TAB==='living') content = renderLivingMembers(false);
  if(ACTIVE_TAB==='progress') content = renderProgressOverview();
  if(ACTIVE_TAB==='activity') content = renderActivityLog();
  if(ACTIVE_TAB==='directory') content = renderFamilyDirectory();
  if(ACTIVE_TAB==='dua') content = renderDua();
  if(ACTIVE_TAB==='sync') content = mDriveSync();
  if(ACTIVE_TAB==='about') content = renderAbout();
  document.getElementById('app').innerHTML = shell(`${esc(member.name)}`, MEMBER_TABS, ACTIVE_TAB, content, `Signed in as ${esc(member.name)}${duaTag()}`);
}
let SELECTED_MARHOOM_ID = null;
function mMarkDone(actor){
  if(!DB.marhooms.length) return card('<p class="text-gray-400 text-center py-10">The Family Owner hasn\u2019t added a Marhoom yet.</p>');
  if(!SELECTED_MARHOOM_ID || !DB.marhooms.find(m=>m.id===SELECTED_MARHOOM_ID)) SELECTED_MARHOOM_ID = DB.marhooms[0].id;
  const m = DB.marhooms.find(x=>x.id===SELECTED_MARHOOM_ID);
  const s = marhoomStats(m.id);
  const mine = memberContribution(m.id, actor.id);
  const tabs = DB.marhooms.map(x=>`<button onclick="SELECTED_MARHOOM_ID='${x.id}';render()" class="px-4 py-2 rounded-lg text-sm font-bold mr-2 mb-2" style="${x.id===m.id?'background:var(--emerald);color:#fff':'background:var(--sand);color:var(--emerald-deep)'}">${esc(x.name)}</button>`).join('');
  return `
  ${card(`
    <div class="mb-3">${tabs}</div>
    <div class="flex flex-col md:flex-row gap-6 items-start">
      <div class="flex flex-col items-center gap-2 flex-shrink-0">
        ${m.photo?`<img src="${m.photo}" class="w-16 h-16 rounded-full object-cover border-2" style="border-color:var(--gold)">`:'<span class="text-4xl">🕊️</span>'}
        ${ring(s.totalPct, 110, 10, 'Family Total')}
      </div>
      <div class="flex-1 w-full">
        <h2 class="text-xl font-bold" style="color:var(--emerald-deep)">${esc(m.name)}'s Qaza Namaz</h2>
        <p class="text-sm text-gray-500 mb-1">${s.totalDone} of ${s.totalTarget} completed by the whole family · ${s.totalRemaining} remaining</p>
        <div class="mb-2">${wasalBlock(m,s)}</div>
        <p class="text-sm font-bold mb-3" style="color:var(--emerald)">Your contribution so far: ${mine.total} prayers</p>
        <div class="grid grid-cols-2 md:grid-cols-3 gap-3">
          ${PRAYERS.map(p=>{
            const st = s.perPrayer[p.key]; const myCount = mine.rec[p.key]||0;
            return `<div class="prayer-tile" id="tile-${p.key}">
              <div class="flex justify-between text-sm font-bold mb-1"><span>${p.label}</span><span>${st.done}/${st.target}</span></div>
              ${bar(st.pct)}
              <div class="text-xs text-gray-500 mt-2 mb-2">You've completed: <b>${myCount}</b></div>
              <div class="flex gap-2">
                <button onclick="incPrayer('${m.id}','${p.key}',1,this)" class="plus-btn">✅ Ada Kiya (+1)</button>
                ${myCount>0?`<button onclick="incPrayer('${m.id}','${p.key}',-1,this)" title="Undo" class="minus-btn">−1</button>`:''}
              </div>
            </div>`;
          }).join('')}
        </div>
      </div>
    </div>
  `)}`;
}
function incPrayer(marhoomId, prayerKey, delta, btn){
  const actorId = getActor().id;
  if(!DB.progress[marhoomId]) DB.progress[marhoomId] = {};
  if(!DB.progress[marhoomId][actorId]) DB.progress[marhoomId][actorId] = emptyCounts();
  const rec = DB.progress[marhoomId][actorId];
  rec[prayerKey] = Math.max(0, (Number(rec[prayerKey])||0) + delta);
  DB.activity.unshift({id:uid(), ts:Date.now(), marhoomId, memberId:actorId, prayer:prayerKey, delta});
  DB.activity = DB.activity.slice(0,300);
  saveDB();
  if(btn && delta>0){ btn.classList.add('pulse'); setTimeout(()=>render(), 180); }
  else render();
}

/* ============================================================
   LIVING MEMBERS — "Meri Namaz" (member's own screen) + the shared
   family-wide "Zinda Members" list. See livingQazaStats() above for
   the calculation itself; everything here is just registration form
   handling, daily-mark buttons, the Qaza pay-down counter, and the
   Owner's "mark as passed away" conversion into a Marhoom record.
   ============================================================ */
function getSelfTrackRecord(){
  if(!SESSION) return null;
  if(SESSION.role==='owner') return DB.config.ownerAccount || null;
  return DB.members.find(m=>m.id===SESSION.memberId) || null;
}
function mMyQaza(){
  const record = getSelfTrackRecord();
  if(!record) return card(`<p class="text-gray-500">Record nahi mila.</p>`);
  if(!record.profile || !record.profile.registeredAt) return mRegistrationForm();
  const s = livingQazaStats(record);
  const today = todayISO();
  const todayMarks = (record.dailyMarks && record.dailyMarks[today]) || {};
  if(!s.isBaligh){
    return card(`
      <h2 class="text-xl font-bold mb-3" style="color:var(--emerald-deep)">🙏 Meri Namaz</h2>
      <p class="text-sm text-gray-600">Aap ki Baligh (Namaz Wajib hone ki) tareekh: <b>${esc(s.balighISO)}</b> (${esc(toHijri(s.balighISO))}).</p>
      <p class="text-sm text-gray-500 mt-2">Is tareekh tak pohanchne ke baad, yahan aap ki roz ki Namaz aur Qaza ka hisaab khud shuru ho jayega.</p>
    `);
  }
  return `
  ${card(`
    <h2 class="text-xl font-bold mb-1" style="color:var(--emerald-deep)">🙏 Aaj ki Wajib Namaz — ${esc(today)}</h2>
    <p class="text-sm text-gray-500 mb-4">Jo waqt aaj mark nahi hoga, wo kal se aap ke Qaza box mein khud shamil ho jayega.</p>
    <div class="grid grid-cols-2 md:grid-cols-5 gap-3">
      ${PRAYERS.map(p=>`
        <button onclick="toggleTodayMark('${p.key}')" class="prayer-tile text-center" style="${todayMarks[p.key]?'border-color:var(--emerald);background:var(--emerald-pale)':''}">
          <div class="text-2xl mb-1">${todayMarks[p.key]?'✅':'⬜'}</div>
          <div class="font-bold text-sm">${p.label}</div>
        </button>
      `).join('')}
    </div>
  `)}
  ${card(`
    <h2 class="text-xl font-bold mb-1" style="color:var(--emerald-deep)">📿 Meri Qaza Namaz</h2>
    <p class="text-sm text-gray-500 mb-4">Kul baqi Qaza: <b style="color:var(--emerald)">${s.totalRemaining}</b> (${s.totalOwed} mein se ${s.totalAda} ada ki ja chuki hai)</p>
    <div class="grid grid-cols-2 md:grid-cols-3 gap-3">
      ${PRAYERS.map(p=>{
        const st = s.perWaqt[p.key];
        return `<div class="prayer-tile">
          <div class="flex justify-between text-sm font-bold mb-1"><span>${p.label}</span><span>${st.ada}/${st.owed}</span></div>
          ${bar(st.owed? Math.min(st.ada/st.owed*100,100) : 100)}
          <div class="text-xs text-gray-500 mt-2 mb-2">Baqi Qaza: <b style="color:var(--danger)">${st.remaining}</b></div>
          <div class="flex gap-2">
            <button onclick="incLivingQaza('${p.key}',1)" class="plus-btn">✅ Qaza Ada Ki (+1)</button>
            ${st.ada>0?`<button onclick="incLivingQaza('${p.key}',-1)" title="Undo" class="minus-btn">−1</button>`:''}
          </div>
        </div>`;
      }).join('')}
    </div>
  `)}
  ${SESSION.role==='owner' ? card(`
    <h2 class="text-lg font-bold mb-2" style="color:var(--danger)">🕊️ Wasal / Intiqal</h2>
    <p class="text-sm text-gray-600 mb-3">Allah na kare, agar aap ka intiqal ho jaye, to koi bhi khud-ba-khud aap ka record Marhoom section mein nahi bhej sakta — ye sirf aap ke muqarrar kiye hue <b>Co-Owner</b> apne khud ke Member login se kar sakenge, jis ke foran baad wo khud naye Family Owner ban jayenge. Apna Co-Owner "Family Members" tab mein muqarrar karein.</p>
    <button onclick="ACTIVE_TAB='members';render()" class="rounded-lg px-5 py-2 font-bold" style="background:var(--sand-dark);color:var(--ink)">⭐ Family Members mein Co-Owner Muqarrar Karein</button>
  `) : (DB.config.ownerAccount && DB.config.ownerAccount.coOwnerId===SESSION.memberId ? card(`
    <h2 class="text-lg font-bold mb-2" style="color:var(--danger)">🕊️ Wasal / Intiqal</h2>
    <p class="text-sm text-gray-600 mb-3">Aap is family ke muqarrar shuda <b>⭐ Co-Owner</b> hain. Allah na kare, agar Family Owner (<b>${esc(DB.config.ownerAccount.name)}</b>) ka intiqal ho jaye, to yahan se aap unka record — baqi Qaza samet — Marhoom section mein shift kar sakte hain. Is ke foran baad, aap khud is family ke naye Family Owner ban jayenge.</p>
    <button onclick="coOwnerMarkOwnerWasal()" class="rounded-lg px-5 py-2 font-bold text-white" style="background:var(--danger)">🕊️ Owner Ka Wasal Darj Karein</button>
  `) : '')}`;
}
